{
  "findings": [
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that direct messages and party chats can be disabled with parental controls.",
      "stance": "mitigation",
      "quote": "Direct messages and party chats can be disabled with parental controls."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that chats built into the coding of specific mini-games cannot be disabled.",
      "stance": "risk",
      "quote": "Chats built into the coding of specific mini-games cannot be disabled, and kids can type text on \"signs\" regardless of communication preferences."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "A parent reports that Roblox uses Robux, a digital currency, for in-game purchases and that targeted ads do not appear for users under 13.",
      "stance": "risk",
      "quote": "Key elements of the games include ads, official product placements, and the need for Robux, the platform's digital currency, to access gated extras. Marketing can be limited, though not completely resolved, by turning off targeted ads. Targeted ads do not appear for users under the age of 13."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that Roblox may process age verification images through third-party providers without guaranteeing a fixed retention period.",
      "stance": "risk",
      "quote": "Images used for age verification may be processed by third-party providers, but Roblox does not publicly guarantee a fixed retention period for the images of children."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that the age verification system can make mistakes, potentially loosening protections for younger users or restricting older users.",
      "stance": "risk",
      "quote": "Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories. Under Roblox’s newer system, users age 5 to 8 may be placed into \"Roblox Kids\" accounts, while users age 9 to 15 may be placed into \"Roblox Select\" accounts. However, the system can make mistakes. Incorrect age estimates may loosen built-in protections, such as chat restrictions or access limits, while some adults may be incorrectly categorized as younger users and face additional restrictions."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that extreme violence, inappropriate language, and sexually explicit content can be found in games accessible to children as young as 5.",
      "stance": "risk",
      "quote": "Extreme violence, inappropriate language, and sexually explicit content is possible (and quite likely) within the user-created games. This advanced content can be limited with the content maturity controls in settings, but much of the adult content that is labeled 5+ may still contain inappropriate content."
    },
    {
      "ref": "[D522]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and potential fines for data collection and age verification practices.",
      "stance": "risk",
      "quote": "Roblox uses AI-based age estimation and verification systems for some users. Users over age 13 may be asked to submit a live selfie or upload a government ID to access certain communication features. Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories."
    }
  ]
}
